import React from 'react';

export default function Footer() {
  return (
    <>
      {/* Injecting keyframes and hover rules */}
      <style>
        {`
          @keyframes rgbGlow {
            0% { filter: hue-rotate(0deg); }
            100% { filter: hue-rotate(360deg); }
          }
          .rgb-animated-logo {
            animation: rgbGlow 6s linear infinite;
          }
          .footer-social:hover {
            background-color: #00D2C4 !important;
            color: #000 !important;
            transform: translateY(-3px);
            box-shadow: 0 0 15px rgba(0, 210, 196, 0.5);
          }
          .footer-link:hover {
            color: #00D2C4 !important;
            padding-left: 4px;
          }
        `}
      </style>

      <footer style={{
        backgroundColor: '#040914',
        color: '#ffffff',
        borderTop: '1px solid rgba(255, 255, 255, 0.05)',
        padding: '72px 24px 48px 24px',
        fontFamily: 'Arial, sans-serif'
      }}>
        <div style={{
          maxWidth: '1200px',
          margin: '0 auto',
          display: 'grid',
          gridTemplateColumns: 'repeat(auto-fit, minmax(220px, 1fr))',
          gap: '40px',
          marginBottom: '48px'
        }}>
          
          {/* Brand & Description */}
          <div style={{ gridColumn: 'span 2' }}>
            <div style={{ display: 'flex', alignItems: 'center', gap: '12px', marginBottom: '16px' }}>
              <div className="rgb-animated-logo" style={{
                width: '38px',
                height: '38px',
                borderRadius: '10px',
                background: 'linear-gradient(135deg, #00D2C4, #ff007f, #7928ca, #0070f3)',
                backgroundSize: '300% 300%',
                display: 'flex',
                alignItems: 'center',
                justifyContent: 'center',
                color: '#fff',
                fontWeight: 'bold',
                padding: '2px',
                boxShadow: '0 4px 12px rgba(0, 210, 196, 0.3)'
              }}>
                <div style={{
                  width: '100%',
                  height: '100%',
                  backgroundColor: '#040914',
                  borderRadius: '8px',
                  display: 'flex',
                  alignItems: 'center',
                  justifyContent: 'center',
                  overflow: 'hidden',
                  position: 'relative'
                }}>
                  <img 
                    src="/assets/logo.png" 
                    alt="Logo" 
                    onError={(e) => { e.target.style.display = 'none'; }} 
                    style={{ width: '100%', height: '100%', objectFit: 'cover' }}
                  />
                  <span style={{ position: 'absolute', fontSize: '12px', color: '#00D2C4' }}>VA</span>
                </div>
              </div>
              <span style={{ fontSize: '20px', fontWeight: 'bold', letterSpacing: '0.5px' }}>Vighnavi Academy</span>
            </div>
            
            <p style={{ color: '#d1d5db', fontSize: '15px', lineHeight: '1.7', maxWidth: '380px', marginBottom: '24px' }}>
              Empowering learners to become skilled, confident, and industry-ready developers through quality education, mentorship, and practical learning.
            </p>
            
            <div style={{ display: 'flex', gap: '14px' }}>
              {['f', 'in', 'ig', 'yt'].map((social, idx) => (
                <a key={idx} href="#" className="footer-social" style={{
                  width: '40px',
                  height: '40px',
                  borderRadius: '50%',
                  backgroundColor: 'rgba(255, 255, 255, 0.05)',
                  color: '#fff',
                  display: 'flex',
                  alignItems: 'center',
                  justifyContent: 'center',
                  textDecoration: 'none',
                  fontSize: '15px',
                  fontWeight: '600',
                  transition: 'all 0.3s ease'
                }}>{social}</a>
              ))}
            </div>
          </div>

          {/* Quick Links */}
          <div>
            <h4 style={{ fontSize: '16px', fontWeight: 'bold', marginBottom: '18px', color: '#fff', letterSpacing: '0.5px' }}>Quick Links</h4>
            <ul style={{ listStyle: 'none', padding: 0, margin: 0 }}>
              {['Home', 'Courses', 'About Us', 'Testimonials', 'Contact Us'].map((link, idx) => (
                <li key={idx} style={{ marginBottom: '12px' }}>
                  <a href={`#${link.toLowerCase().replace(' ', '')}`} className="footer-link" style={{ color: '#9ca3af', textDecoration: 'none', fontSize: '15px', transition: 'all 0.2s ease', display: 'inline-block' }}>{link}</a>
                </li>
              ))}
            </ul>
          </div>

          {/* Courses */}
          <div>
            <h4 style={{ fontSize: '16px', fontWeight: 'bold', marginBottom: '18px', color: '#fff', letterSpacing: '0.5px' }}>Courses</h4>
            <ul style={{ listStyle: 'none', padding: 0, margin: 0 }}>
              {['Python Masterclass', 'Java Masterclass', 'All Courses'].map((course, idx) => (
                <li key={idx} style={{ marginBottom: '12px' }}>
                  <a href="#" className="footer-link" style={{ color: '#9ca3af', textDecoration: 'none', fontSize: '15px', transition: 'all 0.2s ease', display: 'inline-block' }}>{course}</a>
                </li>
              ))}
            </ul>
          </div>

        </div>

        {/* Bottom Bar / Contact Details */}
        <div style={{
          maxWidth: '1200px',
          margin: '0 auto',
          paddingTop: '32px',
          borderTop: '1px solid rgba(255, 255, 255, 0.05)',
          display: 'flex',
          flexDirection: 'column',
          alignItems: 'center',
          justifyContent: 'space-between',
          gap: '16px',
          fontSize: '14px',
          color: '#9ca3af',
          textAlign: 'center'
        }}>
          <div>
            <p style={{ margin: 0 }}>📞 +91 98765 43210 &nbsp;&nbsp;|&nbsp;&nbsp; ✉️ hello@vighnaviacademy.com</p>
            <p style={{ margin: '6px 0 0 0' }}>📍 India &nbsp;&nbsp;|&nbsp;&nbsp; 🌐 www.vighnaviacademy.com</p>
          </div>
          <p style={{ margin: 0, fontSize: '13px', color: '#6b7280' }}>© 2026 Vighnavi Academy. All Rights Reserved.</p>
        </div>
      </footer>
    </>
  );
}
